def populate(pack,add):
    bundles={code:pack(code,name,SOURCES[code]['url']) for code,name in COURSES.items()}
    for line in DATA.strip().splitlines():
        if not line.strip():continue
        sid,title,teaching,parents,questions=line.split('|',4)
        course,key=sid.split('.',1)
        add(bundles[course],key,title,teaching,questions.replace(';;','\n'),prereq=parents.split(),aliases=[title])
        node=bundles[course]['skills'][-1]
        node['introduced_version']='0.3.0'
        node['learning_steps']=[s+'。' for s in teaching.rstrip('。').split('；')]
        node['source_scope']={'source':course,'mapping':'topic_starter_bank','teacher_reviewed':False}
